def md5(text):
    return hashlib.md5(text.encode("utf-8")).hexdigest()


def outside(text, zone):
    if not zone:
        return text
    i = text.index(zone[0])
    j = text.index(zone[1]) + len(zone[1])
    return text[:i] + text[j:]


def fail(message):
    print(message)
    print("NOTHING was written.")
    return 1


def main():
    planned = []
    notes = []
    for f in FILES:
        rel = f["path"]
        path = os.path.join(HERE, *rel.split("/"))
        if f["mode"] == "new":
            if os.path.exists(path):
                with open(path, "rb") as handle:
                    have = handle.read().decode("utf-8").replace("\r\n", "\n")
                if md5(have) == f["new_md5"]:
                    print("ok  %-50s already present, the same" % rel)
                    continue
                return fail("ERROR: %s already exists and differs from what "
                            "this patch adds." % rel)
            planned.append((rel, path, f["content"]))
            print("ok  %-50s new file" % rel)
            continue
        if not os.path.exists(path):
            return fail("ERROR: %s is not here. Save this patch in the "
                        "orrery's root folder." % rel)
        with open(path, "rb") as handle:
            raw = handle.read()
        try:
            text = raw.decode("utf-8")
        except UnicodeDecodeError:
            return fail("ERROR: %s is not UTF-8." % rel)
        if "\r\n" in text:
            text = text.replace("\r\n", "\n")
            notes.append("note: %s was CRLF in the working copy; written LF"
                         % rel)
        zone = f.get("zone")
        have = md5(outside(text, zone))
        if have == f["new_md5"]:
            return fail("ERROR: %s already carries this patch's change. "
                        "It has run before." % rel)
        if have != f["base_md5"]:
            return fail("ERROR: %s is not the version this patch was built "
                        "on (base moved). Compare it with the repository in "
                        "GitHub Desktop." % rel)
        for n, (old, new) in enumerate(f["edits"], 1):
            count = text.count(old)
            if count != 1:
                first = old.strip().splitlines()[0][:60] if old.strip() else ""
                return fail("ANCHOR FAIL: %s edit %d matched %d times: %r"
                            % (rel, n, count, first))
            text = text.replace(old, new)
        if md5(outside(text, zone)) != f["new_md5"]:
            return fail("ERROR: %s came out different from the tested "
                        "result." % rel)
        planned.append((rel, path, text))
        print("ok  %-50s %d edit(s)" % (rel, len(f["edits"])))

    for rel, path, text in planned:
        directory = os.path.dirname(path)
        if directory:
            os.makedirs(directory, exist_ok=True)
        with open(path, "w", encoding="utf-8", newline="") as handle:
            handle.write(text)
    for note in notes:
        print(note)
    print("Stamps updated: each edited module's docstring, the three skills'")
    print("version lines, and the protocol's header and version history.")
    print("patch applied (%d file(s) written)" % len(planned))
    print("")
    print("NEXT:")
    print("  1. Run the orrery maintenance run (dashboard). It writes the new")
    print("     data/drawings/van_allen_belts.json and the export, and")
    print("     regenerates the skill manifest. Expect 'Drawings export check'")
    print("     to say 5 of 5 planted faults caught, and the scanner's gate")
    print("     line 0 TIER-1.")
    print("  2. Plot Earth with the magnetosphere on (Mode 5): the two belts")
    print("     as curved dots; the belt, magnetosphere, bow shock and LEO")
    print("     hovers.")
    print("  3. Move this script into documentation/, then commit and push.")
    print("  4. Reinstall provenance-discipline (2.30), interactive-exhibit")
    print("     (1.17) and gallery-cache-builder (1.11) in Settings > Skills.")
    print("  5. Then patch 3, in the WEBSITE folder, BEFORE the next Daily Run.")
    return 0


if __name__ == "__main__":
    sys.exit(main())
